/**
 * @param {string[]} queries
 * @param {string[]} words
 * @return {number[]}
 */
var numSmallerByFrequency = function(queries, words) {
    const frequencyOfSmallest = (str) => {
        let smallest = '{';
        let frequency = 0;

        for (const char of str) {
            if (char < smallest) {
                smallest = char;
                frequency = 1;
            } else if (char === smallest) {
                frequency++;
            }
        }

        return frequency;
    };

    const wordFrequencies = words
        .map(frequencyOfSmallest)
        .sort((a, b) => a - b);

    return queries.map((query) => {
        const queryFrequency = frequencyOfSmallest(query);
        let left = 0;
        let right = wordFrequencies.length;

        // Find the first word frequency strictly greater than queryFrequency.
        while (left < right) {
            const middle = Math.floor((left + right) / 2);

            if (wordFrequencies[middle] <= queryFrequency) {
                left = middle + 1;
            } else {
                right = middle;
            }
        }

        return wordFrequencies.length - left;
    });
};
