var eventualSafeNodes = function(graph) {
    const n = graph.length;
    const reverseGraph = Array.from({ length: n }, () => []);
    const outDegree = new Array(n);

    for (let node = 0; node < n; node++) {
        outDegree[node] = graph[node].length;

        for (const next of graph[node]) {
            reverseGraph[next].push(node);
        }
    }

    const queue = [];
    for (let node = 0; node < n; node++) {
        if (outDegree[node] === 0) {
            queue.push(node);
        }
    }

    const safe = new Array(n).fill(false);
    let front = 0;

    while (front < queue.length) {
        const node = queue[front++];
        safe[node] = true;

        for (const previous of reverseGraph[node]) {
            outDegree[previous]--;

            if (outDegree[previous] === 0) {
                queue.push(previous);
            }
        }
    }

    const result = [];
    for (let node = 0; node < n; node++) {
        if (safe[node]) {
            result.push(node);
        }
    }

    return result;
};
