/**
 * @param {string} binary
 * @return {string}
 */
var maximumBinaryString = function(binary) {
    const firstZero = binary.indexOf('0');
    if (firstZero === -1) return binary;

    let zeroCount = 0;
    for (let i = firstZero; i < binary.length; i++) {
        if (binary[i] === '0') zeroCount++;
