var regionsBySlashes = function(grid) {
    const n = grid.length;
    const size = n * 3;
    const expanded = Array.from({ length: size }, () => Array(size).fill(0));

    for (let row = 0; row < n; row++) {
        for (let col = 0; col < n; col++) {
            const char = grid[row][col];

            if (char === '/') {
                expanded[row * 3][col * 3 + 2] = 1;
                expanded[row * 3 + 1][col * 3 + 1] = 1;
                expanded[row * 3 + 2][col * 3] = 1;
            } else if (char === '\\') {
                expanded[row * 3][col * 3] = 1;
                expanded[row * 3 + 1][col * 3 + 1] = 1;
                expanded[row * 3 + 2][col * 3 + 2] = 1;
            }
        }
    }

    const directions = [[1, 0], [-1, 0], [0, 1], [0, -1]];
    let regions = 0;

    for (let row = 0; row < size; row++) {
        for (let col = 0; col < size; col++) {
            if (expanded[row][col] !== 0) continue;

            regions++;
            expanded[row][col] = 1;
            const queue = [[row, col]];
            let head = 0;

            while (head < queue.length) {
                const [currentRow, currentCol] = queue[head++];

                for (const [dr, dc] of directions) {
                    const nextRow = currentRow + dr;
                    const nextCol = currentCol + dc;

                    if (
                        nextRow >= 0 && nextRow < size &&
                        nextCol >= 0 && nextCol < size &&
                        expanded[nextRow][nextCol] === 0
                    ) {
                        expanded[nextRow][nextCol] = 1;
                        queue.push([nextRow, nextCol]);
                    }
                }
            }
        }
    }

    return regions;
};
